commonCss:
:root { --font-family-heading: var(--font-family-body); --font-family-display: var(--font-family-body); }
html[data-front-tone=dark] { --front-bg:#101217; --front-panel:#171a21; --front-raised:#252a35; --front-text:#eef1f6; --front-muted:#a5adbc; --front-border:#343b49; --front-accent:#a8c6ff; }
html[data-front-tone=light] { --front-bg:#f4f5f8; --front-panel:#ffffff; --front-raised:#e9edf4; --front-text:#1d2533; --front-muted:#59667b; --front-border:#c8d0dc; --front-accent:#285bac; }
.App-module__multiRoot { --relay-shell-background:var(--front-bg); --relay-shell-surface:var(--front-panel); --relay-shell-text:var(--front-text); --relay-shell-muted:var(--front-muted); --relay-shell-hover:var(--front-raised); --relay-shell-active:var(--front-raised); --relay-shell-border:var(--front-border); --relay-shell-border-strong:var(--front-border); --relay-shell-focus:var(--front-accent); }
.Titlebar-module__appTitle {font:var(--font-weight-medium) .8125rem/1.3 var(--font-family-body);}
.AppSidebar-module__telegramIcon {width:1.8rem;height:1.8rem;} .AppSidebar-module__xIcon,.AppSidebar-module__instagramIcon {width:1.4rem;height:1.4rem;}
#Main {container-type:inline-size;}
#LeftColumn {width:clamp(17rem,29cqw,21rem)!important;min-width:17rem!important;max-width:21rem!important;box-shadow:none!important;}
#LeftColumn-main .Chat .title,#MiddleColumn .title {font-family:var(--font-family-body)!important;}
.MiddleHeader {border-radius:.625rem!important;box-shadow:none!important;}
.MediaOperationsPanel-module__root {font-family:var(--font-family-body);}
.MediaOperationsPanel-module__header {padding:1.125rem 1.125rem .875rem;}
.MediaOperationsPanel-module__header h2 {font:var(--font-weight-semibold) 1rem/1.35 var(--font-family-body);letter-spacing:-.01em;}
.MediaOperationsPanel-module__tabs {gap:.75rem;padding-inline:1.125rem;}
.MediaOperationsPanel-module__tabs button {border:0;border-radius:0;border-bottom:2px solid transparent;background:none;}
.MediaOperationsPanel-module__tabs button[aria-selected=true] {border-bottom-color:var(--front-accent);color:var(--front-text);background:none;}
.MediaOperationsPanel-module__operation {padding:1.125rem;}
.MediaOperationsPanel-module__operation h3 {font:var(--font-weight-semibold) .9375rem/1.4 var(--font-family-body);letter-spacing:0;}
.MediaOperationsPanel-module__row {font-size:.6875rem;line-height:1.4;gap:.375rem;}
.MediaOperationsPanel-module__stage {font-size:.8125rem;}
.MediaOperationsPanel-module__meta {font-size:.75rem;line-height:1.5;color:var(--front-muted);}
.MediaOperationsPanel-module__operation button {border-radius:.375rem;font-size:.75rem;}
.MediaOperationsPanel-module__progress {height:.25rem;accent-color:var(--front-accent);}
.MediaOperationsPanel-module__footer {font-size:.6875rem;line-height:1.5;padding:1rem;}
.Modal .modal-dialog {border-radius:.875rem!important;border:1px solid var(--front-border);}
.Modal h3,.Modal .modal-title {font-family:var(--font-family-body)!important;font-size:1.125rem;}
.SocialShareModal-module__mode button {font-family:var(--font-family-body)!important;}
@media(prefers-reduced-motion:reduce){[data-front-direction] *{animation:none!important;transition:none!important;}}

html body .MediaOperationsPanel-module__header h2,html body .MediaOperationsPanel-module__operation h3,html body #LeftColumn .title,html body #MiddleColumn .title,html body .Modal .modal-title,html body .Modal h3{font-family:var(--font-family-body)!important;letter-spacing:0!important;}
html body #Main .MiddleHeader{box-shadow:none!important;}
html[data-front-direction=B] body #Main .MiddleHeader{margin:0!important;width:100%!important;max-width:none!important;border-radius:0!important;height:3.5rem!important;border-bottom:1px solid var(--front-border)!important;}
